from pathlib import Path
import json,hashlib,collections
root=Path(__file__).resolve().parents[5]; assets=root/'prototype/icons'; rows=[]
for setpath in json.loads((assets/'catalog.json').read_text())['sets']:
 base=assets/setpath; data=json.loads(base.read_text())
 for item in data['icons']:
  motions=[]
  for motion in item['motions']:
   file=base.parent/(motion['name']+'.lottie'); assert hashlib.sha256(file.read_bytes()).hexdigest()==motion['sha256']
   poses=base.parent/(motion['name']+'-poses.png');assert poses.exists(),poses
   motions.append({'name':motion['name'],'active':motion['active'],'rest':motion['rest'],'sha256':motion['sha256'],'path':str(file.relative_to(assets)),'poses':str(poses.relative_to(assets)),'poseSha256':hashlib.sha256(poses.read_bytes()).hexdigest(),'startState':motion.get('startState','rest'),'endState':motion.get('endState','rest'),'reverse':motion.get('reverse',{}).get('name'),'reverseMeta':({'name':motion['reverse']['name'],'active':motion['reverse']['active'],'rest':motion['reverse']['rest'],'path':str((base.parent/(motion['reverse']['name']+'.lottie')).relative_to(assets)),'poses':str((base.parent/(motion['reverse']['name']+'-poses.png')).relative_to(assets)),'sha256':motion['reverse']['sha256'],'poseSha256':hashlib.sha256((base.parent/(motion['reverse']['name']+'-poses.png')).read_bytes()).hexdigest()} if motion.get('reverse') else None)})
  rows.append({'name':item['name'],'label':item['label'],'set':setpath[:2],'currentIntent':item.get('intent',item.get('description')),'stateful':item.get('stateful',False),'motions':motions})
(root/'motion/icon-sets/library/evidence/director-review/inventory.json').write_text(json.dumps(rows,indent=2)+'\n')
html='''<!doctype html><meta charset="utf-8"><title>Technical motion review</title><style>*{box-sizing:border-box}body{background:#10171d;color:#dce4e9;font:14px system-ui;margin:20px}header{display:flex;gap:24px;align-items:center}button,select{background:#19272e;color:white;border:1px solid #567;border-radius:8px;padding:8px}main{display:grid;grid-template-columns:1fr 1fr;gap:12px}article{border:1px solid #30414a;border-radius:10px;padding:12px;min-width:0}h2{font-size:18px;margin:0}h3{font-size:12px;color:#98adb8;margin:4px 0}img{display:block;width:100%;height:auto}.live{display:flex;align-items:center;gap:18px}.live canvas{background:transparent}output{font:11px monospace;color:#8cafbb}#status{font:12px monospace}p{margin:5px 0;font-size:12px}</style><header><h1>Motion audit</h1><button id="replay" disabled>Replay</button><label>Style <select id="style"><option>outline</option><option>solid</option><option>duotone</option></select></label><span id="status">Loading</span></header><main></main><script type="module">
import{DotLottie}from'../vendor/dotlottie-web.js';DotLottie.setWasmUrl(new URL('../vendor/dotlottie-player.wasm',location.href).href);
const inventory=INVENTORY;const page=Number(new URLSearchParams(location.search).get('page')||0);const rows=new URLSearchParams(location.search).has('reverse')?inventory.filter(r=>r.stateful).map(r=>({...r,label:r.label+' / reverse',motions:r.motions.map(m=>m.reverseMeta)})):inventory.slice(page*8,page*8+8);const players=[];
for(const row of rows){const article=document.createElement('article');article.dataset.icon=row.name;article.innerHTML=`<h2>${row.label}</h2><div class="live"></div>`;document.querySelector('main').append(article);
for(const [i,m]of row.motions.entries()){const group=document.createElement('section');group.innerHTML=`<h3>${i?'Strong':'Light'} · ${m.active}s</h3><img src="${m.poses}?sha=${m.poseSha256}">`;article.append(group);const canvas=document.createElement('canvas');canvas.width=canvas.height=64;canvas.style.width=canvas.style.height='64px';const output=document.createElement('output');output.dataset.motion=m.name;article.querySelector('.live').append(canvas,output);const p=new DotLottie({canvas,src:m.path+'?sha='+m.sha256,autoplay:false,loop:false,useFrameInterpolation:false,renderConfig:{autoResize:false,devicePixelRatio:1,freezeOnOffscreen:false}});await new Promise((resolve,reject)=>{p.addEventListener('load',resolve);p.addEventListener('loadError',()=>reject(Error(m.name)));});p.setSegment(0,m.rest+27);let events=0;p.addEventListener('frame',e=>{output.textContent=m.name+' f'+Math.round(e.currentFrame);output.dataset.events=++events;});players.push(p);}}
function style(){for(const p of players){const s=document.querySelector('#style').value;p.setTheme('dark');for(const w of['light','regular','bold'])p.setScalarSlot('style.outline.'+w,s!=='solid'&&w==='regular'?100:0);p.setScalarSlot('style.solid',s==='solid'?100:0);p.setScalarSlot('style.tint',s==='duotone'?18:0);}}
function replay(){style();for(const p of players){p.setFrame(0);p.play();}}
document.querySelector('#replay').onclick=replay;document.querySelector('#style').onchange=replay;document.querySelector('#replay').disabled=false;document.querySelector('#status').textContent='Ready · '+rows.map(r=>r.label).join(', ');replay();
</script>'''.replace('INVENTORY',json.dumps(rows))
(assets/'.motion-critique.html').write_text(html)
print('Inventoried',len(rows),'icons and',sum(len(r['motions']) for r in rows),'forward profiles; both poses and current package hashes recorded.')
